            (br#"{"Command":"SendMessage","QueueName":7}"#, MissingParameter),
            (br#"{"Command":"SendMessage","QueueName":"q","Body":""}"#, InvalidParameterValue),
            (br#"{"Command":"SendMessage","QueueName":"q","Body":"b","GroupId":"a b"}"#, InvalidParameterValue),
