            (br#"{"Command":"SetQueueAttributes","QueueName":"q","Attributes":{"Color":1}}"#, InvalidParameterValue),
            (br#"{"Command":"SetQueueAttributes","QueueName":"q","Attributes":{"Fifo":"yes"}}"#, InvalidParameterValue),
