            ..AttributeChanges::default()
        };
        assert_eq!(only_queue.dead_letter().map_err(|e| e.code()), Err(ErrorCode::InvalidParameterValue));
        assert_eq!(AttributeChanges::default().dead_letter(), Ok(None));
    }
}
