                receipt_handle: handle,
                body: body.clone(),
                receive_count: count,
                sent_at: *sent_at,
                first_received_at,
                fifo: fifo.clone(),
            });
        }
        let dead = dead
            .into_iter()
            .map(|arrival| self.remove(arrival).expect("dead-lettered message was found in this scan"))
            .collect();
        (delivered, dead)
    }

    fn in_flight(&self, handle: ReceiptHandle, now: Timestamp) -> Result<Arrival, NotInFlight> {
        let arrival = *self.by_handle.get(&handle).ok_or(NotInFlight)?;
        let message = &self.messages[&arrival];
        if message.delivery.state(now) == State::InFlight {
            Ok(arrival)
        } else {
            Err(NotInFlight)
        }
    }

    fn remove(&mut self, arrival: Arrival) -> Option<Message> {
        let message = self.messages.remove(&arrival)?;
        self.by_sent_at.remove(&(message.sent_at, arrival));
        if let Some(handle) = message.delivery.handle() {
            self.by_handle.remove(&handle);
        }
        Some(message)
    }
}

