                sequence_number: self.sequence.next_sequence_number(),
            });
            let at = at(sent_at);
            let body = Body::parse(body.to_owned()).expect("test bodies are valid");
            self.store.push(Message::new(self.ids.next_message_id(), body, at, at, fifo));
        }

        fn receive(
            &mut self,
            now: u32,
