        assert_eq!(f.store.change_visibility(first, at(5), Seconds::new(0)), Ok(()));
        assert_eq!(f.store.delete(first, at(5)), Err(NotInFlight));
        f.receive(5, 1, NO_DEAD_LETTER);
        assert_eq!(f.store.delete(first, at(5)), Err(NotInFlight));
        let second = ReceiptHandle::parse("r-2").expect("r-2 is well formed");
        assert_eq!(f.store.delete(second, at(15)), Err(NotInFlight));
        assert_eq!(f.store.change_visibility(second, at(14), Seconds::new(100)), Ok(()));
        assert_eq!(f.store.delete(second, at(113)), Ok(()));
        assert_eq!(f.store.len(), 0);
