                Ok(Output::Clock { now: self.now })
            }
            Request::SendMessage(send) => self.send_message(send).map(Output::Sent),
            Request::ReceiveMessage(receive) => {
                self.receive_message(&receive).map(|messages| Output::Received { messages })
            }
            Request::DeleteMessage { queue, receipt_handle } => {
                let now = self.now;
                let handle = self.issued_handle(&queue, &receipt_handle)?;
                self.queue_mut(&queue)?
                    .delete_message(handle, now)
                    .map_err(|NotInFlight| Error::ReceiptHandleExpired(handle))?;
                Ok(Output::Empty {})
            }
            Request::ChangeMessageVisibility { queue, receipt_handle, visibility_timeout } => {
                let now = self.now;
                let handle = self.issued_handle(&queue, &receipt_handle)?;
                self.queue_mut(&queue)?
                    .change_visibility(handle, now, visibility_timeout)
                    .map_err(|NotInFlight| Error::ReceiptHandleExpired(handle))?;
                Ok(Output::Empty {})
            }
        }
    }

    /// Looks a queue up by exact name and brings its messages up to date with
    /// retention.
    fn queue_mut(&mut self, name: &str) -> Result<&mut Queue, Error> {
        let queue = self
            .queues
            .get_mut(name)
            .ok_or_else(|| Error::QueueDoesNotExist(name.to_owned()))?;
        queue.expire(self.now);
        Ok(queue)
    }

    /// Checks that `queue` exists, then that `text` is a handle this process
    /// has issued, in the order the spec gives those checks.
    fn issued_handle(&mut self, queue: &str, text: &str) -> Result<ReceiptHandle, Error> {
        self.queue_mut(queue)?;
        ReceiptHandle::parse(text)
            .filter(|&handle| self.receipt_handles.has_issued(handle))
            .ok_or_else(|| Error::ReceiptHandleInvalid(text.to_owned()))
    }

    fn create_queue(&mut self, name: QueueName, changes: &AttributeChanges) -> Result<(), Error> {
        let fifo = changes.fifo.unwrap_or(false);
        if name.has_fifo_suffix() != fifo {
            return Err(Error::QueueNameInvalid {
                rule: "must end in .fifo exactly when the Fifo attribute is true",
            });
        }
        let content_based_deduplication = changes.content_based_deduplication.unwrap_or(false);
        if content_based_deduplication && !fifo {
            return Err(Error::InvalidParameterValue {
                parameter: "ContentBasedDeduplication",
                rule: "can only be true for a FIFO queue",
            });
        }
        let requested = QueueAttributes {
            visibility_timeout: changes.visibility_timeout.unwrap_or(DEFAULT_VISIBILITY_TIMEOUT),
            delay_seconds: changes.delay.unwrap_or(DEFAULT_DELAY),
            retention_seconds: changes.retention.unwrap_or(DEFAULT_RETENTION),
            fifo,
            content_based_deduplication,
            dead_letter: changes.dead_letter()?,
        };
        if let Some(existing) = self.queues.get(&name) {
            return if existing.attributes() == requested {
                Ok(())
            } else {
                Err(Error::QueueAlreadyExists(name))
            };
        }
        let dead_letter = requested
            .dead_letter
            .map(|requested| self.resolve_dead_letter(requested.queue, fifo, requested.max_receive_count))
            .transpose()?;
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::LimitExceeded("1000 queues already exist"));
        }
        self.queues.insert(name, Queue::new(&requested, dead_letter));
        Ok(())
    }

    fn set_queue_attributes(&mut self, name: &str, changes: &AttributeChanges) -> Result<(), Error> {
        // Resolved before the queue is borrowed mutably; nothing is reported
        // until the rules below have run in the spec's order.
        let target = changes
            .dead_letter_queue()
            .map(|target| (target, self.queues.get_key_value(target).map(|(k, q)| (k.clone(), q.is_fifo()))));
        let queue = self.queue_mut(name)?;
        if changes.fifo.is_some() {
            return Err(Error::UnsupportedOperation("the type of a queue never changes"));
        }
        if changes.content_based_deduplication == Some(true) && !queue.is_fifo() {
            return Err(Error::InvalidParameterValue {
                parameter: "ContentBasedDeduplication",
                rule: "can only be true for a FIFO queue",
            });
        }
        let dead_letter = match (changes.dead_letter()?, target) {
            (Some(requested), Some((_, None))) => {
                return Err(Error::QueueDoesNotExist(requested.queue.to_owned()));
            }
            (Some(requested), Some((_, Some((target, target_fifo))))) => {
                if target.as_str() == name || target_fifo != queue.is_fifo() {
                    return Err(Error::InvalidParameterValue {
                        parameter: "DeadLetterQueue",
                        rule: "must be another queue of the same type",
                    });
                }
                Some(DeadLetter { queue: target, max_receive_count: requested.max_receive_count })
            }
            _ => None,
        };
        if let Some(timeout) = changes.visibility_timeout {
            queue.visibility_timeout = timeout;
        }
        if let Some(delay) = changes.delay {
            queue.delay = delay;
        }
        if let Some(retention) = changes.retention {
            queue.retention = retention;
        }
        if let Some(enabled) = changes.content_based_deduplication {
            queue.set_content_based_deduplication(enabled);
        }
        if dead_letter.is_some() {
            queue.dead_letter = dead_letter;
        }
        Ok(())
    }

    /// Checks that `name` is an existing queue of the given type and returns the
    /// configuration that refers to it.
    fn resolve_dead_letter(
        &self,
        name: &str,
        fifo: bool,
        max_receive_count: crate::types::MaxReceiveCount,
    ) -> Result<DeadLetter, Error> {
        let (queue, target) = self
            .queues
            .get_key_value(name)
            .ok_or_else(|| Error::QueueDoesNotExist(name.to_owned()))?;
        if target.is_fifo() != fifo {
            return Err(Error::InvalidParameterValue {
                parameter: "DeadLetterQueue",
                rule: "must be a queue of the same type",
            });
        }
        Ok(DeadLetter { queue: queue.clone(), max_receive_count })
    }

    fn delete_queue(&mut self, name: &str) -> Result<(), Error> {
        self.queues
            .remove(name)
            .ok_or_else(|| Error::QueueDoesNotExist(name.to_owned()))?;
        for queue in self.queues.values_mut() {
            if queue.dead_letter.as_ref().is_some_and(|d| d.queue.as_str() == name) {
                queue.dead_letter = None;
            }
        }
        Ok(())
    }

    fn send_message(&mut self, send: SendMessage) -> Result<Sent, Error> {
        let now = self.now;
        let Self { queues, message_ids, .. } = self;
        let queue = queues
            .get_mut(send.queue.as_str())
            .ok_or_else(|| Error::QueueDoesNotExist(send.queue.clone()))?;
        queue.expire(now);
        queue.send(send, now, message_ids)
    }

    fn receive_message(&mut self, receive: &ReceiveMessage) -> Result<Vec<ReceivedMessage>, Error> {
        let now = self.now;
        // The queue is taken out of the map so that its dead-letter queue can be
        // borrowed mutably at the same time; a queue is never its own
        // dead-letter queue, and the queue goes back before returning.
        let (name, mut queue) = self
            .queues
            .remove_entry(receive.queue.as_str())
            .ok_or_else(|| Error::QueueDoesNotExist(receive.queue.clone()))?;
        queue.expire(now);
        let (delivered, dead) = queue.receive(
            now,
            receive.max_messages,
            receive.visibility_timeout,
            &mut self.receipt_handles,
        );
        if let Some(dead_letter) = &queue.dead_letter
            && let Some(target) = self.queues.get_mut(&dead_letter.queue)
        {
            for message in dead {
                target.accept_dead_letter(message, now);
            }
        }
        self.queues.insert(name, queue);
        Ok(delivered)
    }
}

