            let request = if name.ends_with(".fifo") {
                create_with(name, json!({"Fifo": true}))
            } else {
                create(name)
            };
            (request, ok())
        })
        .collect();
    session.extend([
        (
            json!({"Command": "ListQueues"}),
            json!({"ok": true, "QueueNames": ["9", "A", "a", "a-x", "a.fifo", "a_", "b"]}),
        ),
        (
            json!({"Command": "ListQueues", "Prefix": "a"}),
            json!({"ok": true, "QueueNames": ["a", "a-x", "a.fifo", "a_"]}),
        ),
        (json!({"Command": "ListQueues", "Prefix": "a-"}), json!({"ok": true, "QueueNames": ["a-x"]})),
        (json!({"Command": "ListQueues", "Prefix": "c"}), json!({"ok": true, "QueueNames": []})),
        (json!({"Command": "ListQueues", "Prefix": 1}), fail("InvalidParameterValue")),
    ]);
    check(&session);
}

#[test]
fn delete_queue_clears_dead_letter_references_and_forgets_everything() {
    check(&[
        (create("dlq"), ok()),
        (create_with("q", json!({"DeadLetterQueue": "dlq", "MaxReceiveCount": 1})), ok()),
        (send("dlq", "m"), sent(1)),
        (json!({"Command": "DeleteQueue", "QueueName": "dlq"}), ok()),
        (json!({"Command": "DeleteQueue", "QueueName": "dlq"}), fail("QueueDoesNotExist")),
        (get_attributes("q"), json!({"ok": true, "Attributes": default_attributes(), "Counts": counts(0, 0, 0)})),
        (create_with("dlq", json!({"VisibilityTimeout": 1})), ok()),
        (get_attributes("dlq"), {
            let mut attributes = default_attributes();
            attributes["VisibilityTimeout"] = json!(1);
            json!({"ok": true, "Attributes": attributes, "Counts": counts(0, 0, 0)})
        }),
        (get_attributes("q"), json!({"ok": true, "Attributes": default_attributes(), "Counts": counts(0, 0, 0)})),
    ]);
}

#[test]
fn purge_removes_messages_in_every_state() {
    check(&[
        (create("q"), ok()),
        (send("q", "a"), sent(1)),
        (json!({"Command": "SendMessage", "QueueName": "q", "Body": "b", "DelaySeconds": 10}), sent(2)),
        (send("q", "c"), sent(3)),
        (crate::common::receive("q", 1), crate::common::messages(json!([{
            "MessageId": "m-1", "ReceiptHandle": "r-1", "Body": "a",
            "ReceiveCount": 1, "SentAt": 0, "FirstReceivedAt": 0,
        }]))),
        (get_attributes("q"), json!({"ok": true, "Attributes": default_attributes(), "Counts": counts(1, 1, 1)})),
        (json!({"Command": "PurgeQueue", "QueueName": "q"}), ok()),
        (get_attributes("q"), json!({"ok": true, "Attributes": default_attributes(), "Counts": counts(0, 0, 0)})),
        (crate::common::delete_message("q", "r-1"), fail("ReceiptHandleExpired")),
    ]);
}

