use std::io::Write;
use std::process::{Command, Stdio};

use serde_json::json;

use crate::common::{check, create, fail, ok, responses, send, sent, tick};

#[test]
fn every_line_gets_one_response_in_order() {
    let input = b"\n[1]\n{\"Command\":\"Tick\",\"Seconds\":2}\n\xff\xfe\n{\"Command\":\"Tick\",\"Seconds\":3}";
    assert_eq!(
        responses(input),
        vec![
            fail("InvalidRequest"),
            fail("InvalidRequest"),
            json!({"ok": true, "Now": 2}),
            fail("InvalidRequest"),
            json!({"ok": true, "Now": 5}),
        ]
    );
}

#[test]
fn empty_input_and_trailing_newline_add_no_response() {
    assert_eq!(responses(b""), vec![]);
    assert_eq!(responses(b"{\"Command\":\"Tick\",\"Seconds\":1}\n"), vec![json!({"ok": true, "Now": 1})]);
}

#[test]
fn request_shape_errors() {
    check(&[
        (json!({"command": "Tick", "Seconds": 1}), fail("InvalidRequest")),
        (json!({"Command": null}), fail("InvalidRequest")),
        (json!({"Command": ["Tick"]}), fail("InvalidRequest")),
        (json!({"Command": "Purge"}), fail("InvalidRequest")),
        (json!("Tick"), fail("InvalidRequest")),
    ]);
}

#[test]
fn unknown_members_are_ignored_and_null_means_absent() {
    check(&[
        (json!({"Command": "Tick", "Seconds": 1, "Verbose": true}), json!({"ok": true, "Now": 1})),
        (json!({"Command": "Tick", "Seconds": null}), fail("MissingParameter")),
        (json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"DelaySeconds": null}}), ok()),
        (json!({"Command": "SendMessage", "QueueName": "q", "Body": "b", "DelaySeconds": null}), sent(1)),
    ]);
}

#[test]
fn integers_must_be_written_without_fraction_or_exponent() {
    let input = b"{\"Command\":\"Tick\",\"Seconds\":1.0}\n\
        {\"Command\":\"Tick\",\"Seconds\":1e0}\n\
        {\"Command\":\"Tick\",\"Seconds\":\"1\"}\n\
        {\"Command\":\"Tick\",\"Seconds\":-0}\n\
        {\"Command\":\"Tick\",\"Seconds\":1209600}\n\
        {\"Command\":\"Tick\",\"Seconds\":1209601}\n";
    assert_eq!(
        responses(input),
        vec![
            fail("InvalidParameterValue"),
            fail("InvalidParameterValue"),
            fail("InvalidParameterValue"),
            json!({"ok": true, "Now": 0}),
            json!({"ok": true, "Now": 1_209_600}),
            fail("InvalidParameterValue"),
        ]
    );
}

#[test]
fn checks_run_in_the_specified_order() {
    check(&[
        // Required presence beats a bad value of another parameter.
        (json!({"Command": "SendMessage", "QueueName": 1}), fail("MissingParameter")),
        // A bad value beats an unknown queue.
        (json!({"Command": "SendMessage", "QueueName": "nope", "Body": ""}), fail("InvalidParameterValue")),
        (send("nope", "b"), fail("QueueDoesNotExist")),
        // Queue lookup beats the receipt handle checks.
        (json!({"Command": "DeleteMessage", "QueueName": "nope", "ReceiptHandle": "x"}), fail("QueueDoesNotExist")),
        // CreateQueue checks the name before other parameters.
        (json!({"Command": "CreateQueue", "QueueName": "a b", "Attributes": 3}), fail("QueueNameInvalid")),
        // Any string is looked up as given.
        (json!({"Command": "PurgeQueue", "QueueName": "a b"}), fail("QueueDoesNotExist")),
        (create("q"), ok()),
        (json!({"Command": "PurgeQueue", "QueueName": "Q"}), fail("QueueDoesNotExist")),
        (tick(0), json!({"ok": true, "Now": 0})),
    ]);
}

#[test]
fn binary_answers_each_line_and_exits_zero_at_end_of_input() {
    let mut child = Command::new(env!("CARGO_BIN_EXE_miniq"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .expect("the miniq binary starts");
    child
        .stdin
        .take()
        .expect("stdin is piped")
        .write_all(b"{\"Command\":\"Tick\",\"Seconds\":4}\n{\"Command\":\"ListQueues\"}")
        .expect("miniq reads its input");
    let output = child.wait_with_output().expect("miniq runs to completion");
    assert_eq!(output.status.code(), Some(0));
    assert_eq!(
        String::from_utf8_lossy(&output.stdout),
        "{\"ok\":true,\"Now\":4}\n{\"ok\":true,\"QueueNames\":[]}\n"
    );
}

use serde_json::json;

use crate::common::{
    check, counts, create, create_with, fail, get_attributes, ok, responses, send, sent, tick,
};

fn default_attributes() -> serde_json::Value {
    json!({
        "VisibilityTimeout": 30,
        "DelaySeconds": 0,
        "RetentionSeconds": 345_600,
        "Fifo": false,
        "ContentBasedDeduplication": false,
    })
}

fn set(queue: &str, attributes: serde_json::Value) -> serde_json::Value {
    json!({"Command": "SetQueueAttributes", "QueueName": queue, "Attributes": attributes})
}

#[test]
fn create_queue_rules() {
    check(&[
        (create("q.fifo"), fail("QueueNameInvalid")),
        (create_with("q", json!({"Fifo": true})), fail("QueueNameInvalid")),
        (create_with("q", json!({"ContentBasedDeduplication": true})), fail("InvalidParameterValue")),
        (create_with("q", json!({"MaxReceiveCount": 3})), fail("InvalidParameterValue")),
        (create_with("q", json!({"DeadLetterQueue": "d"})), fail("InvalidParameterValue")),
        (create_with("q", json!({"Colour": "red"})), fail("InvalidParameterValue")),
        (create_with("q", json!({"DelaySeconds": 901})), fail("InvalidParameterValue")),
        (create_with("q", json!({"DeadLetterQueue": "d", "MaxReceiveCount": 3})), fail("QueueDoesNotExist")),
        (create("q"), ok()),
        // Same attributes after defaults: succeeds and changes nothing.
        (create_with("q", json!({"VisibilityTimeout": 30, "Fifo": false})), ok()),
        (create_with("q", json!({"VisibilityTimeout": 31})), fail("QueueAlreadyExists")),
        // The existing queue is compared before the dead-letter queue is looked up.
        (create_with("q", json!({"DeadLetterQueue": "none", "MaxReceiveCount": 1})), fail("QueueAlreadyExists")),
        (create_with("d.fifo", json!({"Fifo": true})), ok()),
        (create_with("s", json!({"DeadLetterQueue": "d.fifo", "MaxReceiveCount": 3})), fail("InvalidParameterValue")),
        (create_with("s", json!({"DeadLetterQueue": "q", "MaxReceiveCount": 3})), ok()),
        (create_with("s", json!({"DeadLetterQueue": "q", "MaxReceiveCount": 3})), ok()),
        (create_with("s", json!({"DeadLetterQueue": "q", "MaxReceiveCount": 4})), fail("QueueAlreadyExists")),
        (create_with("q", json!({"DeadLetterQueue": "s", "MaxReceiveCount": 4})), fail("QueueAlreadyExists")),
        (
            get_attributes("s"),
            json!({"ok": true, "Attributes": {
                "VisibilityTimeout": 30, "DelaySeconds": 0, "RetentionSeconds": 345_600,
                "Fifo": false, "ContentBasedDeduplication": false,
                "DeadLetterQueue": "q", "MaxReceiveCount": 3,
            }, "Counts": counts(0, 0, 0)}),
        ),
    ]);
}

#[test]
fn queue_limit_is_one_thousand() {
    let mut input: String = (0..1000).map(|i| format!("{}\n", create(&format!("q{i}")))).collect();
    input.push_str(&format!("{}\n{}\n", create("q0"), create("extra")));
    let responses = responses(input.as_bytes());
    assert_eq!(responses.len(), 1002);
    assert!(responses[..1000].iter().all(|r| *r == ok()));
    assert_eq!(responses[1000..], [ok(), fail("LimitExceeded")]);
}

#[test]
fn set_queue_attributes_rules() {
    check(&[
        (create("q"), ok()),
        (create("other"), ok()),
        (create_with("f.fifo", json!({"Fifo": true})), ok()),
        (json!({"Command": "SetQueueAttributes", "QueueName": "q"}), fail("MissingParameter")),
        (set("nope", json!({})), fail("QueueDoesNotExist")),
        (set("q", json!({"Fifo": false})), fail("UnsupportedOperation")),
        (set("q", json!({"Fifo": 1})), fail("InvalidParameterValue")),
        (set("q", json!({"ContentBasedDeduplication": true})), fail("InvalidParameterValue")),
        (set("q", json!({"MaxReceiveCount": 2})), fail("InvalidParameterValue")),
        (set("q", json!({"DeadLetterQueue": "nope", "MaxReceiveCount": 2})), fail("QueueDoesNotExist")),
        (set("q", json!({"DeadLetterQueue": "q", "MaxReceiveCount": 2})), fail("InvalidParameterValue")),
        (set("q", json!({"DeadLetterQueue": "f.fifo", "MaxReceiveCount": 2})), fail("InvalidParameterValue")),
        // A failed command changes nothing, even attributes it could have set.
        (set("q", json!({"VisibilityTimeout": 5, "Fifo": false})), fail("UnsupportedOperation")),
        (get_attributes("q"), json!({"ok": true, "Attributes": default_attributes(), "Counts": counts(0, 0, 0)})),
        (set("q", json!({})), ok()),
        (set("q", json!({"VisibilityTimeout": 5, "DeadLetterQueue": "other", "MaxReceiveCount": 2})), ok()),
        (set("q", json!({"DelaySeconds": 7, "DeadLetterQueue": null, "ContentBasedDeduplication": false})), ok()),
        (set("f.fifo", json!({"ContentBasedDeduplication": true})), ok()),
        (
            get_attributes("q"),
            json!({"ok": true, "Attributes": {
                "VisibilityTimeout": 5, "DelaySeconds": 7, "RetentionSeconds": 345_600,
                "Fifo": false, "ContentBasedDeduplication": false,
                "DeadLetterQueue": "other", "MaxReceiveCount": 2,
            }, "Counts": counts(0, 0, 0)}),
        ),
        (
            get_attributes("f.fifo"),
            json!({"ok": true, "Attributes": {
                "VisibilityTimeout": 30, "DelaySeconds": 0, "RetentionSeconds": 345_600,
                "Fifo": true, "ContentBasedDeduplication": true,
            }, "Counts": counts(0, 0, 0)}),
        ),
    ]);
}

#[test]
fn lowering_retention_removes_messages_for_good() {
    check(&[
        (create("q"), ok()),
        (send("q", "old"), sent(1)),
        (tick(100), json!({"ok": true, "Now": 100})),
        (send("q", "new"), sent(2)),
        (set("q", json!({"RetentionSeconds": 60})), ok()),
        (set("q", json!({"RetentionSeconds": 1000})), ok()),
        (get_attributes("q").clone(), {
            let mut attributes = default_attributes();
            attributes["RetentionSeconds"] = json!(1000);
            json!({"ok": true, "Attributes": attributes, "Counts": counts(1, 0, 0)})
        }),
    ]);
}

#[test]
fn retention_removes_a_message_exactly_at_its_deadline() {
    check(&[
        (create_with("q", json!({"RetentionSeconds": 60})), ok()),
        (send("q", "m"), sent(1)),
        (tick(59), json!({"ok": true, "Now": 59})),
        (get_attributes("q"), json!({"ok": true, "Attributes": {
            "VisibilityTimeout": 30, "DelaySeconds": 0, "RetentionSeconds": 60,
            "Fifo": false, "ContentBasedDeduplication": false,
        }, "Counts": counts(1, 0, 0)})),
        (tick(1), json!({"ok": true, "Now": 60})),
        (get_attributes("q"), json!({"ok": true, "Attributes": {
            "VisibilityTimeout": 30, "DelaySeconds": 0, "RetentionSeconds": 60,
            "Fifo": false, "ContentBasedDeduplication": false,
        }, "Counts": counts(0, 0, 0)})),
    ]);
}

#[test]
fn list_queues_in_byte_order_with_prefix() {
    let names = ["b", "a_", "a", "A", "a-x", "9", "a.fifo"];
    let mut session: Vec<_> = names
        .iter()
        .map(|&name| {
            let request = if name.ends_with(".fifo") {
