        ),
        (
            json!({"Command": "ListQueues", "Prefix": "a"}),
            json!({"ok": true, "QueueNames": ["a", "a-x", "a.fifo", "a_"]}),
        ),
        (json!({"Command": "ListQueues", "Prefix": "a-"}), json!({"ok": true, "QueueNames": ["a-x"]})),
        (json!({"Command": "ListQueues", "Prefix": "c"}), json!({"ok": true, "QueueNames": []})),
        (json!({"Command": "ListQueues", "Prefix": 1}), fail("InvalidParameterValue")),
    ]);
    check(&session);
}

#[test]
fn delete_queue_clears_dead_letter_references_and_forgets_everything() {
    check(&[
        (create("dlq"), ok()),
        (create_with("q", json!({"DeadLetterQueue": "dlq", "MaxReceiveCount": 1})), ok()),
        (send("dlq", "m"), sent(1)),
        (json!({"Command": "DeleteQueue", "QueueName": "dlq"}), ok()),
        (json!({"Command": "DeleteQueue", "QueueName": "dlq"}), fail("QueueDoesNotExist")),
        (get_attributes("q"), json!({"ok": true, "Attributes": default_attributes(), "Counts": counts(0, 0, 0)})),
        (create_with("dlq", json!({"VisibilityTimeout": 1})), ok()),
        (get_attributes("dlq"), {
