use serde_json::{Value, json};

use crate::common::{
    check, counts, create, create_with, delete_message, fail, get_attributes, messages, ok,
    receive, responses, send, send_fifo, sent, sent_fifo, tick,
};

fn now(seconds: u32) -> Value {
    json!({"ok": true, "Now": seconds})
}

fn message(id: u32, handle: u32, body: &str, count: u32, sent_at: u32, first: u32) -> Value {
    json!({
        "MessageId": format!("m-{id}"), "ReceiptHandle": format!("r-{handle}"), "Body": body,
        "ReceiveCount": count, "SentAt": sent_at, "FirstReceivedAt": first,
    })
}

fn fifo_message(
    id: u32,
    handle: u32,
    body: &str,
    count: u32,
    group: &str,
    sequence: u32,
) -> Value {
    let mut message = message(id, handle, body, count, 0, 0);
    message["GroupId"] = json!(group);
    message["SequenceNumber"] = json!(sequence);
    message
}

fn change_visibility(queue: &str, handle: &str, timeout: u32) -> Value {
    json!({"Command": "ChangeMessageVisibility", "QueueName": queue, "ReceiptHandle": handle, "VisibilityTimeout": timeout})
}

fn fifo_queue(name: &str) -> Value {
    create_with(name, json!({"Fifo": true}))
}

fn attributes(queue_counts: Value) -> Value {
    json!({"ok": true, "Attributes": {
        "VisibilityTimeout": 30, "DelaySeconds": 0, "RetentionSeconds": 345_600,
        "Fifo": false, "ContentBasedDeduplication": false,
    }, "Counts": queue_counts})
}

#[test]
fn send_parameter_rules() {
    check(&[
        (create("q"), ok()),
        (fifo_queue("f.fifo"), ok()),
        (json!({"Command": "SendMessage", "QueueName": "q", "Body": "x".repeat(1025)}), fail("InvalidParameterValue")),
        (json!({"Command": "SendMessage", "QueueName": "q", "Body": "b", "DelaySeconds": 901}), fail("InvalidParameterValue")),
        (json!({"Command": "SendMessage", "QueueName": "q", "Body": "b", "GroupId": "g"}), fail("UnsupportedOperation")),
        (json!({"Command": "SendMessage", "QueueName": "q", "Body": "b", "DeduplicationId": "d"}), fail("UnsupportedOperation")),
        (json!({"Command": "SendMessage", "QueueName": "f.fifo", "Body": "b", "DelaySeconds": 0, "GroupId": "g", "DeduplicationId": "d"}), fail("UnsupportedOperation")),
        (json!({"Command": "SendMessage", "QueueName": "f.fifo", "Body": "b", "DeduplicationId": "d"}), fail("MissingParameter")),
        (json!({"Command": "SendMessage", "QueueName": "f.fifo", "Body": "b", "GroupId": "g"}), fail("MissingParameter")),
        // Failed sends use up no message id.
        (send("q", "b"), sent(1)),
        (send_fifo("f.fifo", "b", "g", "d"), sent_fifo(2, 1)),
    ]);
}

#[test]
fn delay_hides_messages_until_it_ends() {
    check(&[
        (create_with("q", json!({"DelaySeconds": 5})), ok()),
        (send("q", "queue delay"), sent(1)),
        (json!({"Command": "SendMessage", "QueueName": "q", "Body": "no delay", "DelaySeconds": 0}), sent(2)),
        (get_attributes("q"), json!({"ok": true, "Attributes": {
            "VisibilityTimeout": 30, "DelaySeconds": 5, "RetentionSeconds": 345_600,
            "Fifo": false, "ContentBasedDeduplication": false,
        }, "Counts": counts(1, 0, 1)})),
        (receive("q", 10), messages(json!([message(2, 1, "no delay", 1, 0, 0)]))),
        (tick(5), now(5)),
        (receive("q", 10), messages(json!([message(1, 2, "queue delay", 1, 0, 5)]))),
    ]);
}

#[test]
fn visibility_timeout_returns_messages_to_their_place() {
    check(&[
        (create("q"), ok()),
        (send("q", "a"), sent(1)),
        (send("q", "b"), sent(2)),
        (json!({"Command": "ReceiveMessage", "QueueName": "q", "VisibilityTimeout": 10}), messages(json!([message(1, 1, "a", 1, 0, 0)]))),
        (receive("q", 10), messages(json!([message(2, 2, "b", 1, 0, 0)]))),
        (tick(10), now(10)),
        (receive("q", 10), messages(json!([message(1, 3, "a", 2, 0, 0)]))),
        (tick(20), now(30)),
        (receive("q", 10), messages(json!([message(2, 4, "b", 2, 0, 0)]))),
        (attributes_request(), attributes(counts(0, 2, 0))),
        (json!({"Command": "ReceiveMessage", "QueueName": "q", "VisibilityTimeout": 43_201}), fail("InvalidParameterValue")),
    ]);
}

fn attributes_request() -> Value {
    get_attributes("q")
}

#[test]
fn zero_visibility_timeout_never_yields_a_usable_handle() {
    check(&[
        (create_with("q", json!({"VisibilityTimeout": 0})), ok()),
        (send("q", "a"), sent(1)),
        (receive("q", 10), messages(json!([message(1, 1, "a", 1, 0, 0)]))),
        (delete_message("q", "r-1"), fail("ReceiptHandleExpired")),
        (receive("q", 10), messages(json!([message(1, 2, "a", 2, 0, 0)]))),
        (attributes_request(), json!({"ok": true, "Attributes": {
            "VisibilityTimeout": 0, "DelaySeconds": 0, "RetentionSeconds": 345_600,
            "Fifo": false, "ContentBasedDeduplication": false,
        }, "Counts": counts(1, 0, 0)})),
    ]);
}

#[test]
fn receipt_handle_rules() {
    check(&[
        (create("q"), ok()),
        (create("other"), ok()),
        (send("q", "a"), sent(1)),
        (send("other", "b"), sent(2)),
        (receive("q", 1), messages(json!([message(1, 1, "a", 1, 0, 0)]))),
        (receive("other", 1), messages(json!([message(2, 2, "b", 1, 0, 0)]))),
        (delete_message("q", "r-3"), fail("ReceiptHandleInvalid")),
        (delete_message("q", "r-01"), fail("ReceiptHandleInvalid")),
        (delete_message("q", "R-1"), fail("ReceiptHandleInvalid")),
        (delete_message("q", "r-1 "), fail("ReceiptHandleInvalid")),
        (change_visibility("q", "r-0", 5), fail("ReceiptHandleInvalid")),
        (delete_message("q", "r-2"), fail("ReceiptHandleExpired")),
        (change_visibility("q", "r-1", 43_201), fail("InvalidParameterValue")),
        (json!({"Command": "ChangeMessageVisibility", "QueueName": "q", "ReceiptHandle": "r-1"}), fail("MissingParameter")),
        (change_visibility("q", "r-1", 100), ok()),
        (tick(99), now(99)),
        (delete_message("q", "r-1"), ok()),
        (delete_message("q", "r-1"), fail("ReceiptHandleExpired")),
        (change_visibility("other", "r-2", 0), ok()),
        (change_visibility("other", "r-2", 10), fail("ReceiptHandleExpired")),
        (receive("other", 1), messages(json!([message(2, 3, "b", 2, 0, 99)]))),
        (delete_message("other", "r-2"), fail("ReceiptHandleExpired")),
        (delete_message("other", "r-3"), ok()),
        (attributes_request(), attributes(counts(0, 0, 0))),
    ]);
}

#[test]
fn fifo_receive_delivers_one_message_per_free_group() {
    check(&[
